/*
 * Five-letter word lists for /Games/Word Puzzle.html.
 *
 * ANSWERS are the words the puzzle can pick. ALLOWED is the larger set a guess is
 * checked against. Every word is five letters, so both are packed with no separator.
 *
 * ANSWERS: 3450 words.  ALLOWED: 6421 words (ANSWERS is a subset, so every answer is
 * always a legal guess).
 *
 * Derived from SCOWL (size-graded English word lists) by Kevin Atkinson.
 * SCOWL's terms require this notice travel with the lists:
 *
 * The collective work is Copyright 2000-2018 by Kevin Atkinson as well
 * as any of the copyrights mentioned below:
 *
 *   Copyright 2000-2018 by Kevin Atkinson
 *
 *   Permission to use, copy, modify, distribute and sell these word
 *   lists, the associated scripts, the output created from the scripts,
 *   and its documentation for any purpose is hereby granted without fee,
 *   provided that the above copyright notice appears in all copies and
 *   that both that copyright notice and this permission notice appear in
 *   supporting documentation. Kevin Atkinson makes no representations
 *   about the suitability of this array for any purpose. It is provided
 *   "as is" without express or implied warranty.
 */

window.NomadWords = {
  ANSWERS: "",
  ALLOWED: "",
  at: function (pack, i) { return pack.substr(i * 5, 5); },
  count: function (pack) { return pack.length / 5; },
  has: function (pack, w) {
    // binary search - both packs are sorted, so this is ~13 probes
    var lo = 0, hi = pack.length / 5 - 1;
    while (lo <= hi) {
      var mid = (lo + hi) >> 1, s = pack.substr(mid * 5, 5);
      if (s === w) return true;
      if (s < w) lo = mid + 1; else hi = mid - 1;
    }
    return false;
  }
};
